typedef struct { unsigned char x, y, map, tx, ty, dir; } Warp;
typedef struct { unsigned char x, y; const char *text; } Sign;
// say: lines when flag is clear (gift: before), alt: when set (gift: after, trainer: after the battle)
// party: (id, level) pairs, nvar sets of them (the rival's depends on your starter: STARTERS order)
typedef struct { const char *name; unsigned char sight, money, nparty, nvar, badge, tm, rival; unsigned short beat, rival_flag, flag; const unsigned char *party; const char *const *intro, *const *after, *const *win; const char *lose; } Trainer;
// cond: flag ids ANDed, 0x8000 = must be clear, 0-terminated. legend/lv: a sleeping creature to battle. opens: map+1 a tablet opens.
typedef struct { unsigned char x, y, dir, look; unsigned short flags; unsigned char item, count; unsigned short flag; const char *const *say, *const *alt; const Trainer *tr; const unsigned short *cond; unsigned char legend, lv, opens; } Npc;
typedef struct { const char *name, *rows; unsigned char w, h, flags, nwarps, nnpcs, nsigns; const Warp *warps; const Npc *npcs; const Sign *signs; unsigned char grass[12], lvlo, lvhi, rate, song, nstock; const unsigned char *stock; const char *town; unsigned char node, water[12], wlo, whi, wrate, fish[12], flo, fhi; char border; } MapInfo;
typedef struct { unsigned char map, x, y; unsigned short been; unsigned char node; } Fly;
extern const Fly FLY[];
#define FLY_COUNT 11 // grass: wild slots (0: none)
typedef struct { unsigned char map, x, y, dir; } Home;
// notes: midi (0 rest) and length in quarter beats. Drums (noise parts): 36 kick, 38 snare, 42 closed hat, 46 open hat
// (older parts use 72 snare and 96 hat). duty 0..3 (12.5, 25, 50, 75 %), decay 0 holds the note or 1..7 fades it by
// hardware steps, vib: vibrato depth after the note has sounded a moment.
typedef struct { unsigned char wave; unsigned short vol; unsigned short n; const unsigned char *notes; unsigned char duty, decay, vib; } SongCh;
typedef struct { unsigned char bpm, loop, nch; const SongCh *ch; } Song;
extern const Song SONGS[];
extern const unsigned short SQ_RATE[128], WV_RATE[128];
enum { SONG_TITLE, SONG_WORLD, SONG_BATTLE, SONG_WIN, SONG_HARBOR, SONG_CAVE, SONG_TRAINER, SONG_SPOTTED, SONG_HEAL, SONG_BIKE, SONG_VOLTARA, SONG_ASH, SONG_MIREWOOD, SONG_SURF, SONG_INTRO, SONG_LEVELUP, SONG_CAUGHT, SONG_LEGEND, SONG_TOWN, SONG_LUMEN, SONG_GYM, SONG_LEADER, SONG_RIVAL, SONG_ASHBATTLE, SONG_MART, SONG_REST, SONG_EVO, SONG_FROST, SONG_DRAKE, SONG_VICTORY, SONG_ELITE, SONG_CHAMPION, SONG_HOF, SONG_COVE, SONG_DUNES, SONG_COUNT };
extern const MapInfo MAP_INFO[];
#define MAP_INFO_COUNT MAP_COUNT
extern const Home HOME;
extern const char *const ITEM_NAME[];
// ball: x10 catch bonus; heal: HP; cure: bit per status (1 par .. 6 frz); revive: back with half HP
// tm: the move a TM teaches. pocket: 0 ITEMS, 1 BALLS, 2 TM CASE, 3 KEY ITEMS. kind: 1 repel, 2 rope, 3 bike, 4 rod, 5 map, 6 held (steps: boosted type + 1, 0 LEFTOVERS)
typedef struct { unsigned char ball, heal, cure, revive; unsigned short price, tm; unsigned char pocket, kind, steps; const char *label, *desc; } Item;
extern const Item ITEMS[];
extern const char PLAYER_NAME[];
// gear bits: beard pack glasses goggles headband feather stripes net gi hardhat brim cape ash mantle bolt bow clips
typedef struct { unsigned cap, shirt, hair, legs; unsigned char long_hair, coat; unsigned gear; } Look;
extern const Look LOOK_DATA[];
#define LOOK_DATA_COUNT 42
extern const unsigned char STARTERS[3];
extern const char *const BADGE_NAME[];
extern const unsigned short BADGE_FLAG[]; // badge b (0 = TIDE) is story flag BADGE_FLAG[b]

